import test from 'node:test';
import assert from 'node:assert/strict';
import {newGame,save,restore} from './simulation.js';
import {characterPersonalities,personalityReaction} from './character-personality.js';
import {characterActing} from './character-acting.js';
import {generateDialogueTurn} from './dialogue-generator.js';
import {thinkingCampaign} from './survival-thinking-fixtures.js';
import {refreshSurvivalThinking,survivalThinkingView,thinkingPlanLine} from './survival-thinking.js';
import {dialogueServiceContext} from './dialogue-service.js';
import {openConversation} from './dialogue.js';
import {introduce} from './identity.js';
import {launchSurvivalSortie} from './survival-base.js';
import {combatGridPage} from './combat-grid-ui.js';
test('confirmed calm personalities distinguish visible fear and self-directed learning without inventing skill or employment',()=>{assert.match(characterPersonalities.yeogyeong.summary,/차분.*귀여운.*겁/);assert.match(characterPersonalities.seoyeon.summary,/자기 주관.*피겨.*양궁.*돈.*레슨/);assert.equal(personalityReaction('yeogyeong',{fear:40,danger:true}).visible,true);assert.equal(personalityReaction('seoyeon',{fear:40,danger:true}).visible,false);assert.equal(personalityReaction('yeogyeong',{fear:80,danger:false}).visible,false);});
test('Yeogyeong shows fear through existing real facial poses and hearing it, with pure rendering and recovery',()=>{const s=newGame(),before=save(s);for(const text of ['깜짝 놀랐어요.','문이 쾅 닫혀서 무서워요.','겁을 먹었어요.']){const a=characterActing(s,'yeogyeong',{text});assert.ok(a.fearReaction.visible);assert.ok(['worried','surprised'].includes(a.emotion));assert.notEqual(a.row,null);assert.match(a.name,/겁먹/);}assert.equal(characterActing(s,'yeogyeong',{listening:true,heardText:'문이 쾅 닫혔다.'}).fearReaction.visible,true);assert.equal(characterActing(s,'yeogyeong',{text:'고마워요. 같이 점심 먹어요.'}).fearReaction.visible,false);assert.equal(personalityReaction('yeogyeong',{text:'이제 안 무서워요.'}).visible,false);assert.equal(save(s),before);});
test('new everyday conversation subjects speak about fear and self-funded lessons and retain exact saved output',()=>{for(const [id,topic,match] of [['yeogyeong','startle',/놀|무서|겁|숨/],['seoyeon','self-directed',/돈|레슨|비용|배우|준비/]]){let found=false;for(let seed=1;seed<20;seed++){const s=newGame();s.clock.minute=820;introduce(s,id,'test');s.dialogue.generation={rng:seed*1234567,sequence:0,recent:{}};const result=generateDialogueTurn(s,id,{topic,action:'greet'});assert.equal(result.plan.topic,topic);assert.ok(!result.text.includes('undefined'));if(match.test(result.text))found=true;assert.deepEqual(restore(save(s)),s);}assert.ok(found);}});
test('survival planning stays calm in safety and gives Yeogyeong caution versus Seoyeon ownership of decisions',()=>{let s=thinkingCampaign(null,'supply');s.survivalRun.members[2].character='yeogyeong';s.survivalRun.members[2].label='차여경';delete s.survivalRun.thinking;s=refreshSurvivalThinking(s);const plans=survivalThinkingView(s),y=plans.find(p=>p.speaker==='member-2'),h=plans.find(p=>p.speaker==='ally');assert.equal(y.goal,'supply:kiosk');assert.match(thinkingPlanLine(s,y),/무섭|겁먹|안전/);assert.match(thinkingPlanLine(s,h),/내가|마음먹|준비/);s.survivalRun.resources.food=30;s.survivalRun.resources.water=30;s.survivalRun.threat=10;delete s.survivalRun.thinking;s=refreshSurvivalThinking(s);assert.ok(!/무섭|겁먹/.test(thinkingPlanLine(s,survivalThinkingView(s).find(p=>p.speaker==='member-2'))));});
test('combat fear is visible for Yeogyeong without editing fear stats or changing battle outcomes',()=>{let s=thinkingCampaign(null,'supply');s.survivalRun.members[1].character='yeogyeong';s.survivalRun.members[1].label='차여경';s=launchSurvivalSortie(s,'kiosk');s.combatTrial.actors.ally.fear=40;const before=save(s),html=combatGridPage(s);assert.match(html,/data-face="yeogyeong" data-fear="visible"/);assert.match(html,/겁먹은 기색/);assert.equal(save(s),before);});
test('server dialogue receives the same confirmed traits as the offline game',()=>{for(const id of ['yeogyeong','seoyeon']){let s=newGame();s.clock.minute=820;introduce(s,id,'test');s=openConversation(s,id).state;const context=dialogueServiceContext(s,id,{plan:{},text:'',turnId:'test'});assert.ok(context.character.includes(characterPersonalities[id].summary));}});
